def countVertex(N: int, edges: list[tuple[int, int]]) -> int:
    if N == 1:
        return 1

    from collections import defaultdict
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    leaves = []
    for node in range(1, N+1):
        if len(graph[node]) == 1:
            leaves.append(node)

    selected = 0
    remaining_nodes = N

    while remaining_nodes > 0:
        if not leaves:
            selected += 1
            break

        leaf = leaves.pop()
        selected += 1
        remaining_nodes -= 1

        for neighbor in graph[leaf]:
            graph[neighbor].remove(leaf)
            if len(graph[neighbor]) == 1 and neighbor != 1:  # Avoid adding root if it's the last node
                leaves.append(neighbor)

    return selected
